<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\PlatformIdentity\Domain\ValueObject\Accessor;

use Civi\Lughauth\Features\Access\PlatformIdentity\Domain\ValueObject\PlatformIdentityUserVO;
use Civi\Lughauth\Features\Access\User\Domain\UserRef;

trait PlatformIdentityUserAccessor
{
    private PlatformIdentityUserVO $_user;
    public function getUser(): UserRef
    {
        return $this->_user->value();
    }
    public function user(): PlatformIdentityUserVO
    {
        return $this->_user;
    }
    public function isUserChanged(?self $original = null): bool
    {
        return !$this->_user->equals($original?->_user);
    }
    public function withUser(PlatformIdentityUserVO|UserRef $user): self
    {
        $copy = clone $this;
        $copy->_user = PlatformIdentityUserVO::from($user);
        return $copy;
    }
}
